style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Remove Roblox's default background */
  html, body, #react-app, .rbx-body, #container, .container-main,
  .home-container, .content, .section-content {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  /* GIF Background Layer */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    background-image: url("https://www.image2url.com/r2/default/gifs/1781786573045-af5c4f45-3089-4c32-a229-610d57db37ba.gif") !important;
    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;
    background-attachment: fixed;
    pointer-events: none;
  }

  /* Optional: Slight dark overlay for better readability */
  body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    background: rgba(0, 0, 0, 0.4); /* Adjust opacity as needed */
    pointer-events: none;
  }

  /* Make main content readable on top */
  #react-app, .rbx-body, .container-main, .section, .card, 
  .rbx-card, .game-card-container {
    background: rgba(20, 20, 20, 0.75) !important; /* semi-transparent dark panels */
    backdrop-filter: blur(8px);
    border-radius: 8px;
  }

  /* Text contrast */
  body, p, span, h1, h2, h3, a, button {
    color: #e6e6e6 !important;
  }
}
